Dans votre code JavaScript, envoyez les poids au store avant l'ouverture du flow de paywall :

```typescript showLineNumbers title="showWeightPaywall.ts"
import { adapty, createFlowView } from 'react-native-adapty';
import NativeWeightPlanStore from './specs/NativeWeightPlanStore';

export async function showWeightPaywall(currentWeight: number, goalWeight: number) {
  try {
    // the native resolver builds the chart from these weights
    NativeWeightPlanStore.setWeights(currentWeight, goalWeight);
    const flow = await adapty.getFlow('weight_paywall');
    const view = await createFlowView(flow);
    await view.present();
  } catch (error) {
    // handle the error
  }
}
```
